// Answers are generated by the server, not the browser tab. The tab only
// watches. Closing or reloading the tab never stops or loses an answer:
// text is flushed to SQLite every FLUSH_MS, and any watcher that connects
// gets everything so far, then the rest as it arrives.

import {
  assembleContext,
  ContextBudgetError,
  describeError,
  type ErrorKind,
  type MessageError,
  type MessageStatus,
} from '@noema/core';
import type { Config } from '../config.ts';
import { ProviderError, type Usage } from '../llm/provider.ts';
import type { ModelSource } from '../llm/settings.ts';
import type { Logger } from '../log.ts';
import type { Repo } from '../store/repo.ts';
import { SYSTEM_PROMPT } from './prompt.ts';

export const FLUSH_MS = 200;

export interface Watcher {
  delta(text: string): void;
  status(status: MessageStatus, error: MessageError | null): void;
  end(): void;
}

interface Live {
  messageId: string;
  revisionId: string;
  content: string;
  status: MessageStatus;
  error: MessageError | null;
  watchers: Set<Watcher>;
  controller: AbortController;
  stopReason: 'user' | 'shutdown' | null;
  done: Promise<void>;
}

export interface StartArgs {
  threadId: string;
  notebookId: string;
  messageId: string;
  revisionId: string;
  question: { id: string; content: string; seq: number };
}

export class Generations {
  private readonly live = new Map<string, Live>();
  private readonly repo: Repo;
  private readonly models: ModelSource;
  private readonly config: Pick<Config, 'contextBudgetTokens' | 'maxOutputTokens'>;
  private readonly log: Logger;

  constructor(deps: {
    repo: Repo;
    models: ModelSource;
    config: Pick<Config, 'contextBudgetTokens' | 'maxOutputTokens'>;
    log: Logger;
  }) {
    this.repo = deps.repo;
    this.models = deps.models;
    this.config = deps.config;
    this.log = deps.log;
  }

  get(messageId: string): Pick<Live, 'content' | 'status' | 'error'> | undefined {
    return this.live.get(messageId);
  }

  get size(): number {
    return this.live.size;
  }

  start(args: StartArgs): void {
    if (this.live.has(args.messageId)) return;
    const entry: Live = {
      messageId: args.messageId,
      revisionId: args.revisionId,
      content: '',
      status: 'pending',
      error: null,
      watchers: new Set(),
      controller: new AbortController(),
      stopReason: null,
      done: Promise.resolve(),
    };
    this.live.set(args.messageId, entry);
    entry.done = this.run(entry, args).catch((err: unknown) => {
      this.log.error('generation crashed', { messageId: args.messageId, err });
    });
  }

  /** Watch a live answer. Returns null if it is not live (read it from the store instead). */
  watch(messageId: string, watcher: Watcher): (() => void) | null {
    const entry = this.live.get(messageId);
    if (!entry) return null;
    entry.watchers.add(watcher);
    return () => entry.watchers.delete(watcher);
  }

  stop(messageId: string): boolean {
    const entry = this.live.get(messageId);
    if (!entry) return false;
    entry.stopReason ??= 'user';
    entry.controller.abort();
    return true;
  }

  /** Stop everything (server shutdown); the answers are stored as interrupted. */
  async shutdown(): Promise<void> {
    const pending = [...this.live.values()];
    for (const entry of pending) {
      entry.stopReason = 'shutdown';
      entry.controller.abort();
    }
    await Promise.all(pending.map((e) => e.done));
  }

  private emit(entry: Live, fn: (w: Watcher) => void): void {
    for (const w of entry.watchers) {
      try {
        fn(w);
      } catch (err) {
        this.log.warn('watcher threw', { err });
        entry.watchers.delete(w);
      }
    }
  }

  private setStatus(entry: Live, status: MessageStatus, error: MessageError | null): void {
    entry.status = status;
    entry.error = error;
    this.emit(entry, (w) => w.status(status, error));
  }

  private async run(entry: Live, args: StartArgs): Promise<void> {
    const started = Date.now();
    let callId: string | null = null;
    let attempts = 0;
    let firstTokenAt: string | null = null;
    let usage: Usage = {};
    let finishReason: string | null = null;
    let flushedLength = 0;
    const flush = () => {
      if (entry.content.length === flushedLength) return;
      try {
        this.repo.saveContent(entry.revisionId, entry.content);
        flushedLength = entry.content.length;
      } catch (err) {
        // Keep streaming; the final write at the end retries with the full text.
        this.log.error('flush failed', { messageId: entry.messageId, err });
      }
    };
    const timer = setInterval(flush, FLUSH_MS);

    let final: { status: 'done' | 'failed' | 'stopped' | 'interrupted'; error: MessageError | null };
    try {
      // The provider in effect when the question was asked answers it, even if settings change meanwhile.
      const provider = this.models.current();
      if (!provider.configured) throw new ProviderError('not_configured', 'the model provider is not configured');
      const notebook = this.repo.getNotebook(args.notebookId);
      const origin = this.repo.originOf(args.threadId);
      const { messages, manifest } = assembleContext({
        system: SYSTEM_PROMPT,
        aboutMe: notebook?.aboutMe ?? '',
        inherited: this.repo.inheritedHistory(args.threadId),
        ...(origin ? { origin: { quote: origin.anchor.exact } } : {}),
        history: this.repo.history(args.threadId, args.question.seq),
        question: { id: args.question.id, content: args.question.content },
        budgetTokens: this.config.contextBudgetTokens,
      });
      callId = this.repo.startModelCall({
        revisionId: entry.revisionId,
        provider: provider.name,
        model: provider.model,
        manifest,
      });
      const stream = provider.stream({
        messages,
        maxTokens: this.config.maxOutputTokens ?? undefined,
        signal: entry.controller.signal,
      });
      for await (const ev of stream) {
        if (ev.type === 'attempt') attempts = ev.n;
        else if (ev.type === 'usage') usage = ev.usage;
        else if (ev.type === 'finish') finishReason = ev.reason;
        else if (ev.type === 'text') {
          if (entry.status === 'pending') {
            firstTokenAt = new Date().toISOString();
            this.repo.markStreaming(entry.revisionId, provider.model);
            this.setStatus(entry, 'streaming', null);
          }
          entry.content += ev.text;
          this.emit(entry, (w) => w.delta(ev.text));
        }
        if (entry.controller.signal.aborted) break;
      }
      if (entry.controller.signal.aborted) throw new ProviderError('aborted', 'stopped');
      final = { status: 'done', error: null };
    } catch (err) {
      final = this.toFinal(entry, err);
    } finally {
      clearInterval(timer);
    }

    const errorKind: ErrorKind | null = final.error?.kind ?? null;
    if (callId) {
      this.repo.endModelCall(callId, { attempts, firstTokenAt, ...usage, finishReason, errorKind });
    }
    this.repo.finishRevision(entry.revisionId, entry.content, final.status, final.error);
    this.setStatus(entry, final.status, final.error);
    this.emit(entry, (w) => w.end());
    this.live.delete(entry.messageId);
    this.log.info('answer finished', {
      messageId: entry.messageId,
      status: final.status,
      errorKind,
      ms: Date.now() - started,
      chars: entry.content.length,
      attempts,
      cacheHitTokens: usage.cacheHitTokens,
      cacheMissTokens: usage.cacheMissTokens,
    });
  }

  private toFinal(
    entry: Live,
    err: unknown,
  ): { status: 'failed' | 'stopped' | 'interrupted'; error: MessageError | null } {
    if (entry.stopReason === 'shutdown') return { status: 'interrupted', error: null };
    if (entry.stopReason === 'user') return { status: 'stopped', error: null };
    if (err instanceof ContextBudgetError) {
      return { status: 'failed', error: { kind: 'context_too_large', message: describeError('context_too_large') } };
    }
    if (err instanceof ProviderError) {
      const detail = err.kind === 'bad_request' || err.kind === 'internal' ? ` (${err.message})` : '';
      return { status: 'failed', error: { kind: err.kind, message: describeError(err.kind) + detail } };
    }
    this.log.error('unexpected generation error', { messageId: entry.messageId, err });
    return { status: 'failed', error: { kind: 'internal', message: describeError('internal') } };
  }
}
